/* Toolbox Learn 2.4.5: offline-first topic library, OIC practice, review and mock exams. */
(()=>{'use strict';const root=document.getElementById('view');if(!root)return;
const files={study:'maritime-study.json',cbt:'toolbox-cbt.json',speak:'articulation-presence.json',oic:'oic-practice.json'};const data={};const STORE='toolbox-learn-v245';let state={screen:'home',track:'deck',topic:'all',query:'',mode:'study',index:0,answers:{},order:[],selected:null};let saved={bookmarks:[],attempts:[],completed:{}};try{saved={...saved,...JSON.parse(localStorage.getItem(STORE)||'{}')}}catch{};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));const persist=()=>{try{localStorage.setItem(STORE,JSON.stringify(saved))}catch{}};const active=()=>!!document.querySelector('nav [data-tab="learn"].active');
const questions=()=>{let a=state.screen==='cbt'?(data.cbt?.questions||[]):(data.oic?.questions||[]).filter(x=>x.track===state.track);return a.filter(x=>(state.topic==='all'||(x.topic||x.topicId)===state.topic)&&(!state.query||[x.question,x.topic,x.topicId,...(x.options||[])].join(' ').toLowerCase().includes(state.query.toLowerCase())))};
const qtopic=x=>x.topic||data.cbt?.topics?.find(t=>t.id===x.topicId)?.title||x.topicId||'General';const opts=x=>x.options||[];const correct=x=>typeof x.answer==='number'?x.answer:Array.isArray(x.answers)&&x.answers.length===1?x.answers[0]:typeof x.correctIndex==='number'?x.correctIndex:typeof x.correct==='number'?x.correct:typeof x.answerIndex==='number'?x.answerIndex:null;
function header(label,title,subtitle){return `<div class="tl-head"><span class="tl-eyebrow">${esc(label)}</span><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>`}function back(to='home'){return `<button class="tl-back" data-go="${to}">← Back</button>`}
function home(){return header('TOOLBOX ACADEMY','Learn for your next watch','Offline learning, topic search and exam preparation.')+`<div class="tl-grid">${[['deck','OIC Deck','Navigational watch preparation'],['engine','OIC Engine','Engineering watch preparation'],['cbt','OLP / CBT','Search original Toolbox practice by topic'],['study','Maritime Study','Lessons and knowledge checks'],['speak','Communication Practice','28-day professional communication']].map(([id,t,d])=>`<button class="tl-course" data-open="${id}"><span class="tl-symbol">${id==='deck'?'01':id==='engine'?'02':id==='cbt'?'03':id==='study'?'04':'05'}</span><strong>${t}</strong><small>${d}</small><span>Open →</span></button>`).join('')}</div><p class="tl-notice">OIC starter questions are Toolbox-authored practice, not official MARINA questions or answer keys. The MARINA PDFs in the source library are not bundled in this build. Content requires educator review.</p>`}
function bank(){let a=questions();let base=state.screen==='cbt'?data.cbt?.questions||[]:(data.oic?.questions||[]).filter(x=>x.track===state.track);let topics=[...new Set(base.map(qtopic))];let title=state.screen==='cbt'?'Toolbox CBT':state.track==='deck'?'OIC Navigational Watch':'OIC Engineering Watch';return back()+header('SEARCHABLE QUESTION LIBRARY',title,`${a.length} matching questions · offline-ready practice`)+`<div class="tl-tools"><input class="tl-search" id="tl-search" type="search" placeholder="Search question or keyword" value="${esc(state.query)}" aria-label="Search questions"><select id="tl-topic" aria-label="Filter topic"><option value="all">All topics</option>${topics.map(t=>`<option value="${esc(t)}" ${state.topic===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="tl-mode"><button data-mode="study" class="${state.mode==='study'?'selected':''}">Study</button><button data-mode="practice" class="${state.mode==='practice'?'selected':''}">Practice</button><button data-mode="exam" class="${state.mode==='exam'?'selected':''}">Mock exam</button></div><div class="tl-actions"><button data-start="1" class="tl-primary">${state.mode==='exam'?'Start mock exam':state.mode==='practice'?'Practice filtered questions':'Study filtered questions'}</button><button data-bookmarks="1">Bookmarks (${saved.bookmarks.length})</button></div><div class="tl-list">${a.slice(0,100).map((q,i)=>`<button class="tl-item" data-question="${i}"><span><strong>${esc(q.question)}</strong><small>${esc(qtopic(q))} · ${saved.bookmarks.includes(q.id)?'Saved bookmark':'Review question'}</small></span><span>›</span></button>`).join('')||'<p>No matching questions. Try another keyword or topic.</p>'}</div><p class="tl-notice">Source: ${state.screen==='cbt'?'Original Toolbox CBT bank; not official OLP answers.':'Toolbox original practice; not official MARINA question text.'} Always verify against current authoritative references.</p>`}
function session(){let id=state.order[state.index],q=(state.sessionQuestions||[]).find(x=>x.id===id);if(!q)return back(state.screen==='cbt'?'cbt':'bank')+'<p>No questions available.</p>';let ans=state.answers[id];let reveal=state.mode==='study'||state.revealed?.[id];let right=correct(q);return back('bank')+header(state.mode==='exam'?'MOCK EXAM':state.mode==='practice'?'PRACTICE':'STUDY',`Question ${state.index+1} of ${state.order.length}`,qtopic(q))+`<div class="tl-question"><div class="tl-qmeta"><span>${esc(qtopic(q))}</span><button data-bookmark="${esc(q.id)}">${saved.bookmarks.includes(q.id)?'★ Bookmarked':'☆ Bookmark'}</button></div><h2>${esc(q.question)}</h2>${opts(q).map((o,i)=>`<button class="tl-option ${ans===i?'chosen':''} ${reveal&&right===i?'right':''}" data-answer="${i}" ${reveal&&state.mode!=='study'?'disabled':''}>${String.fromCharCode(65+i)}. ${esc(typeof o==='string'?o:o.label||o.text||'')}</button>`).join('')}${reveal?`<p class="tl-feedback">${right===null?'Answer key not available in source.':`Reference answer: ${String.fromCharCode(65+right)}. ${esc(q.explanation||'No explanation provided in the source.')}`}</p>`:state.mode==='practice'?'<button data-reveal="1">Check answer</button>':''}<div class="tl-actions"><button data-prev="1" ${state.index===0?'disabled':''}>Previous</button><button class="tl-primary" data-next="1">${state.index===state.order.length-1?'Finish & save':'Next question'}</button></div></div>`}
function summary(){let a=state.sessionQuestions||[],answered=state.order.filter(id=>state.answers[id]!==undefined),keyed=answered.filter(id=>correct(a.find(x=>x.id===id))!==null),good=keyed.filter(id=>state.answers[id]===correct(a.find(x=>x.id===id)));return back('bank')+header('SESSION COMPLETE','Review your progress',`${answered.length} answered · ${good.length}/${keyed.length} correct on keyed questions`)+`<div class="tl-actions"><button class="tl-primary" data-go="bank">Return to question library</button></div><p class="tl-notice">Results are stored locally on this device. This is not an official certification assessment.</p>`}
function lessons(){let rows=state.screen==='study'?data.study?.lessons||[]:data.speak?.days||[];return back()+header('OFFLINE LESSONS',state.screen==='study'?'Maritime Study':'Communication Practice','Choose a lesson to review.')+`<div class="tl-list">${rows.map((x,i)=>`<button class="tl-item" data-lesson="${i}"><span><strong>${esc(x.title||x.goal||'Day '+(x.day||i+1))}</strong><small>${saved.completed[state.screen+':'+i]?'Completed':'Open lesson'}</small></span>›</button>`).join('')}</div>`}
function lesson(){let rows=state.screen==='study'?data.study?.lessons||[]:data.speak?.days||[];let x=rows[state.selected];if(!x)return lessons();return back(state.screen)+header('LEARNING MATERIAL',x.title||x.goal||'Day '+(x.day||state.selected+1),x.area||'')+`<div class="tl-question"><p>${esc(x.summary||x.description||x.content||x.goal||'See source learning materials for full lesson.')}</p>${(x.keyPoints||x.steps||[]).map(s=>`<p>${esc(typeof s==='string'?s:JSON.stringify(s))}</p>`).join('')}<button class="tl-primary" data-complete="1">${saved.completed[(state.lessonParent||state.screen)+':'+state.selected]?'Completed ✓':'Mark complete'}</button></div>`}
function paint(){if(!active())return;root.innerHTML=`<section class="tl-root tl-245">${state.screen==='home'?home():['bank','cbt'].includes(state.screen)?bank():state.screen==='session'?session():state.screen==='summary'?summary():state.screen==='lesson'?lesson():lessons()}</section>`}
function begin(single=null,bookmarkOnly=false){let a=questions();if(bookmarkOnly)a=a.filter(x=>saved.bookmarks.includes(x.id));if(single!==null)a=a.slice(single,single+1);if(state.mode==='exam'&&single===null){a=a.slice().sort(()=>Math.random()-.5).slice(0,Math.min(20,a.length))}state.sessionQuestions=a;state.order=a.map(x=>x.id);state.index=0;state.answers={};state.revealed={};state.screen='session';paint()}
root.addEventListener('input',e=>{if(!active()||e.target.id!=='tl-search')return;state.query=e.target.value;let pos=e.target.selectionStart;paint();let el=root.querySelector('#tl-search');el?.focus();el?.setSelectionRange(pos,pos)},true);
root.addEventListener('change',e=>{if(e.target.id==='tl-topic'){state.topic=e.target.value;paint()}},true);
root.addEventListener('click',e=>{if(!active())return;let b=e.target.closest('button[data-open],button[data-go],button[data-mode],button[data-start],button[data-question],button[data-answer],button[data-reveal],button[data-next],button[data-prev],button[data-bookmark],button[data-bookmarks],button[data-lesson],button[data-complete]');if(!b)return;e.stopImmediatePropagation();if(b.dataset.open){let v=b.dataset.open;state.screen=v==='deck'||v==='engine'?'bank':v;state.track=v==='engine'?'engine':'deck';state.topic='all';state.query='';state.mode='study'}else if(b.dataset.go){state.screen=b.dataset.go==='bank'?'bank':b.dataset.go;state.selected=null}else if(b.dataset.mode){state.mode=b.dataset.mode}else if(b.dataset.start){begin();return}else if(b.dataset.question!==undefined){begin(Number(b.dataset.question));return}else if(b.dataset.answer!==undefined){let id=state.order[state.index];state.answers[id]=Number(b.dataset.answer)}else if(b.dataset.reveal){state.revealed[state.order[state.index]]=true}else if(b.dataset.next){if(state.index<state.order.length-1)state.index++;else{let a=state.sessionQuestions||[];let keyed=a.filter(x=>correct(x)!==null);let good=keyed.filter(x=>state.answers[x.id]===correct(x)).length;saved.attempts.unshift({date:new Date().toISOString(),mode:state.mode,track:state.track,score:good,total:keyed.length});saved.attempts=saved.attempts.slice(0,100);persist();state.screen='summary'}}else if(b.dataset.prev){state.index=Math.max(0,state.index-1)}else if(b.dataset.bookmark){let id=b.dataset.bookmark;saved.bookmarks=saved.bookmarks.includes(id)?saved.bookmarks.filter(x=>x!==id):[...saved.bookmarks,id];persist()}else if(b.dataset.bookmarks){begin(null,true);return}else if(b.dataset.lesson!==undefined){state.selected=Number(b.dataset.lesson);state.lessonParent=state.screen;state.screen='lesson'}else if(b.dataset.complete){saved.completed[(state.lessonParent||state.screen)+':'+state.selected]=Date.now();persist();state.screen=state.lessonParent||'study'}paint()},true);
const observer=new MutationObserver(()=>{if(active()&&!root.querySelector('.tl-root'))paint()});observer.observe(root,{childList:true});document.querySelectorAll('nav [data-tab="learn"]').forEach(b=>b.addEventListener('click',()=>queueMicrotask(paint)));
Promise.all(Object.entries(files).map(async([id,file])=>{try{let r=await fetch('assets/learning/'+file);if(!r.ok)throw Error('missing');data[id]=await r.json()}catch{data[id]={questions:[],lessons:[],days:[]}}})).then(paint);
})();
